\label{thm:bound_Lieb_Rob}
If $\gamma>d$, then ${\mathcal B}^{\mathop{\oslash}\nolimits^{\gamma}\!\!\!\!}\subset{\mathcal B}_\mathrm{sd}$. Moreover, for any
$\Phi\in{\mathcal B}^{\mathop{\oslash}\nolimits^{\gamma}\!\!\!\!}$, $0<\delta<\gamma-d$ and $t\in{\mathbbm R}$, there exists
a constant $c_{\Phi,\delta,t}$ such that
$$
\left\|\tau_\Phi^t(A)-\tau^t_{\Phi,\Lambda}(A)\right\|
\leq
c_{\Phi,\delta,t}
\frac{|\Lambda'|}
{\left(1+\mathop{\mathrm{dist}}\nolimits(\Lambda',\Lambda^c)\right)^{\delta}}
\|A\|,
$$
provided $A\in{\mathfrak A}_{\Lambda'}$ with $\Lambda'\subset\Lambda\in{\mathcal F}$.

\label{prop:state_properties}
Let $\Phi\in{\mathcal B}^{\mathop{\oslash}\nolimits^{\gamma}\!\!\!\!}$ with $\gamma>2d$ and
$\Psi\in\leftindex_1{\mathcal B}\cap{\mathcal B}_\mathrm{sd}$. Let $t\in{\mathbbm R}$,
$\omega\in{\mathcal S}_\mathrm{eq}(\Psi)$, and consider
$\omega_t=\omega\circ\tau^t_\Phi$. Then the following hold.
\begin{romanenumerate}
\item $\omega_t\in{\mathcal S}_\mathrm{eq}(H(\Psi|\Phi,t))$.
\item $\omega_t$ is an $(\alpha_{H(\Psi|\Phi,t)},1)$-KMS state.
\item $\omega_t$ satisfies the Gibbs condition with respect to $H(\Psi|\Phi,t)$.
\end{romanenumerate}

\label{thm:wgPreserv}
Assume that $\Phi\in{\mathcal B}_\mathrm{f}$.
\begin{romanenumerate}
\item If, for some $r>0$, $\|\Psi\|_r<r$, and $\omega\in{\mathcal S}_\mathrm{wg}(\Psi)$, then
there exists $T>0$ such that $\omega_t\in{\mathcal S}_\mathrm{wg}(H(\Psi|\Phi,t))$ for $|t|<T$.
\item If $d = 1$, $\Psi\in{\mathcal B}_\mathrm{f}$, and $\omega\in{\mathcal S}_\mathrm{wg}(\Psi)$, then 
$\omega_t\in{\mathcal S}_\mathrm{wg}(H(\Psi|\Phi,t))$ for all $t\in{\mathbbm R}$.
\end{romanenumerate}

\label{prop:LRboxes}
Let $\Phi\in{\mathcal B}^{\mathop{\oslash}\nolimits^{\gamma}\!\!\!\!}$ for some $\gamma>d$. For any $t\in{\mathbbm R}$ and
$0<\delta<\gamma-d$, there exists a constant $c_{\Phi,\delta,t}$ such that
\begin{equation}
\left\|\tau_{\Phi,\Lambda}^t(A)
-\tau^t_{\Phi,\widetilde\Lambda}(A)\right\|
\leq
c_{\Phi,\delta,t}
\frac{|\Lambda'|}
{\left(1+\mathop{\mathrm{dist}}\nolimits(\Lambda',\widetilde\Lambda\setminus\Lambda)\right)^\delta}
\|A\|
\label{mar-don}
\end{equation}
for every $\Lambda'\subset\Lambda\subset\widetilde\Lambda\in{\mathcal F}$ and
$A\in{\mathfrak A}_{\Lambda'}$.

Fix $\delta\in(d,\gamma-d)$, choose $\{\Lambda'\}$ satisfying
Properties~(i)--(ii) of Lemma~\ref{lem:boxes}, and set
$\Lambda''=\Lambda\setminus\Lambda'$.  It suffices to show that for some constants $c_1, c_2$ and $c_3$,
\begin{equation}
\left|S(\omega_{t,\Lambda})-S(\omega_{\Lambda,t})\right|
\le c_1|\Lambda'|^2\left(1+\mathop{\mathrm{dist}}\nolimits(\Lambda',\Lambda^c)\right)^{-\delta}
+c_2|\Lambda''|+c_3.
\label{eq:bound_h}
\end{equation}
Indeed,  after division by $|\Lambda|$,
the right-hand side tends to zero by Lemma~\ref{lem:boxes},
proving the result. We proceed to  prove~\eqref{eq:bound_h}.


Denote by $\omega_{\Lambda,t|\Lambda'}$ the restriction of
$\omega_{\Lambda,t}$ to ${\mathfrak A}_{\Lambda'}$.
The Araki--Lieb inequality~\cite{Araki1970} gives  
\begin{align*}
S(\omega_{t,\Lambda'})-S(\omega_{t,\Lambda''})
\le\left|S(\omega_{t,\Lambda'})-S(\omega_{t,\Lambda''})\right|
&\le S(\omega_{t,\Lambda})\le S(\omega_{t,\Lambda'})+S(\omega_{t,\Lambda''}),\\[4pt]
S(\omega_{\Lambda,t|\Lambda'})-S(\omega_{\Lambda,t|\Lambda''})
\le\left|S(\omega_{\Lambda,t|\Lambda'})-S(\omega_{\Lambda,t|\Lambda''})\right|
&\le S(\omega_{\Lambda,t})
\le S(\omega_{\Lambda,t|\Lambda'})+S(\omega_{\Lambda,t|\Lambda''}).
\end{align*}
It follows that
\begin{align*}
S(\omega_{t,\Lambda})-S(\omega_{\Lambda,t})&\le S(\omega_{t,\Lambda'})+S(\omega_{t,\Lambda''})-S(\omega_{\Lambda,t|\Lambda'})+S(\omega_{\Lambda,t|\Lambda''})\\
&\le\left|S(\omega_{t,\Lambda'})-S(\omega_{\Lambda,t|\Lambda'})\right|+S(\omega_{t,\Lambda''})+S(\omega_{\Lambda,t|\Lambda''}),
\end{align*}
and similarly
\begin{align*}
S(\omega_{\Lambda,t})-S(\omega_{t,\Lambda})&\le S(\omega_{\Lambda,t|\Lambda'})+S(\omega_{\Lambda,t|\Lambda''})-S(\omega_{t,\Lambda'})+S(\omega_{t,\Lambda''})\\
&\le\left|S(\omega_{t,\Lambda'})-S(\omega_{\Lambda,t|\Lambda'})\right|+S(\omega_{t,\Lambda''})+S(\omega_{\Lambda,t|\Lambda''}).
\end{align*}
Thus, 
\begin{equation}
\left|S(\omega_{t,\Lambda})-S(\omega_{\Lambda,t})\right|
\leq\left|S(\omega_{t,\Lambda'})-S(\omega_{\Lambda,t|\Lambda'})\right|+S(\omega_{t,\Lambda''})+S(\omega_{\Lambda,t|\Lambda''}),
\label{eq:box_outer00}
\end{equation}
where, with $c_2=2\log\mathop{\mathrm{dim}}\nolimits\,{\mathcal H}$,
\begin{equation}
S(\omega_{t,\Lambda''})+ S(\omega_{\Lambda,t|\Lambda''})\leq c_2|\Lambda''|.
\label{eq:box_outer}
\end{equation}
For these estimates, see also~\cite[Proof of Proposition~2.1]{Wreszinski2019}
and~\cite[Eq.~(56)]{Wreszinski2022}.

For the remaining term in~\eqref{eq:box_outer00}, we use
an argument of Fannes~\cite{Fannes1973}.
 Set $M=\mathop{\mathrm{dim}}\nolimits\,{\mathcal H}_{\Lambda'}=\mathrm{e}^{h|\Lambda'|}$, where $h=\log\mathop{\mathrm{dim}}\nolimits\,{\mathcal H}$, and denote by
$(\alpha_l)_{l\in\llbracket1,M\rrbracket}$ and $(\beta_l)_{l\in\llbracket1,M\rrbracket}$ 
the eigenvalues of $\omega_{t,\Lambda'}$ and
$\omega_{\Lambda,t|\Lambda'}$, respectively, counted with multiplicity
and arranged in increasing order.
Set $\epsilon_l=\beta_l-\alpha_l$, and note that, by~\cite[Theorem~6.11]{Kato1966},
\begin{equation}
a_{\Lambda,\Lambda'}\coloneq\sum_{l\in\llbracket1,M\rrbracket}|\epsilon_l|
\le\|\omega_{t,\Lambda'}-\omega_{\Lambda,t|\Lambda'}\|_1\le2,
\label{eq:abound}
\end{equation}
where $\|\,{\bm\cdot}\,\|_1$ denotes the trace norm. Set ${\mathfrak s}(x)\coloneq-x\log x$ for $x\in(0,1]$, with ${\mathfrak s}(0)=0$.
By~\cite[Lemma~2]{Fannes1973}, for $x,y\in[0,1]$ we have
$$
|{\mathfrak s}(x)-{\mathfrak s}(y)|\leq{\mathfrak s}(|x-y|)+2|x-y|, 
$$
which implies that
\begin{equation}
\left|S(\omega_{t,\Lambda'})-S(\omega_{\Lambda,t|\Lambda'})\right|
\le\sum_{l\in\llbracket1,M\rrbracket}{\mathfrak s}(|\epsilon_l|)+4.
\label{eq:sum_eps0}
\end{equation}
If $a_{\Lambda,\Lambda'}=0$, then the left-hand side
of~\eqref{eq:sum_eps0} vanishes. Otherwise, invoking the concavity of the
logarithm, we get
\begin{align*}
\sum_{l\in\llbracket1,M\rrbracket}{\mathfrak s}(|\epsilon_l|)
&=a_{\Lambda,\Lambda'}
\sum_{\substack{l\in\llbracket1,M\rrbracket\\\epsilon_l\neq0}}
\frac{|\epsilon_l|}{a_{\Lambda,\Lambda'}}
\log\frac1{|\epsilon_l|}
\leq
a_{\Lambda,\Lambda'}
\log\sum_{\substack{l\in\llbracket1,M\rrbracket\\\epsilon_l\neq0}}
\frac1{a_{\Lambda,\Lambda'}}\\[4pt]
&\leq
a_{\Lambda,\Lambda'}(\log M-\log a_{\Lambda,\Lambda'})
\leq
ha_{\Lambda,\Lambda'}|\Lambda'|+\mathrm{e}^{-1},
\end{align*}
which, together with~\eqref{eq:sum_eps0}, yields
\begin{equation}
\left|S(\omega_{t,\Lambda'})-S(\omega_{\Lambda,t|\Lambda'})\right|
\leq ha_{\Lambda,\Lambda'}|\Lambda'|+c_3.
\label{eq:box_inner1}
\end{equation}
By duality, the first inequality in~\eqref{eq:abound} can be written as 
$$
a_{\Lambda,\Lambda'}\leq\sup_{\substack{A\in{\mathfrak A}_{\Lambda'}\\\|A\|\leq1}}
\left|\mathop{\mathrm{tr}}\nolimits\left((\omega_{t,\Lambda'}-\omega_{\Lambda,t|\Lambda'})A\right)\right|,
$$
and since
$$
\left|\mathop{\mathrm{tr}}\nolimits\left((\omega_{t,\Lambda'}-\omega_{\Lambda,t|\Lambda'})A\right)\right|
=\left|\omega\left(\tau_\Phi^t(A)-\tau^t_{\Phi,\Lambda}(A)\right)\right|
\leq\left\|\tau_\Phi^t(A)-\tau^t_{\Phi,\Lambda}(A)\right\|
$$
for $A\in{\mathfrak A}_{\Lambda'}$, it follows from Theorem~\ref{thm:bound_Lieb_Rob} that
$$
a_{\Lambda,\Lambda'}\leq\sup_{\substack{A\in{\mathfrak A}_{\Lambda'}\\\|A\|\leq1}}
\left\|\tau_\Phi^t(A)-\tau_{\Phi,\Lambda}^t(A)\right\|\leq c_t| \Lambda'|\left(1+\mathop{\mathrm{dist}}\nolimits(\Lambda',\Lambda^c)\right)^{-\delta}.
$$
Combining the last inequality with~\eqref{eq:box_outer00}, \eqref{eq:box_outer}
and~\eqref{eq:box_inner1} proves~\eqref{eq:bound_h} with $c_1=hc_t$.
\hfill$\Box$

\label{prop:formula_W}
Under the assumptions of Part~\textup{(ii)} of
Theorem~\ref{thm:W_disapp}, for each $\Lambda\in{\mathcal F}$ the net
$$
\left(
W_{\Lambda,\widetilde\Lambda}(\Psi|\Phi,t)
\right)_{\Lambda\subset\widetilde\Lambda\in{\mathcal F}}
$$
directed by inclusion converges in norm. In particular, the
surface energy
$W(\Psi|\Phi,t)=\left(W_\Lambda(\Psi|\Phi,t)\right)_{\Lambda\in{\mathcal F}}$
of the Hamiltonian family $H(\Psi|\Phi,t)$ is well-defined and is given by
\begin{equation}
W_{\Lambda}(\Psi|\Phi,t)
=
\sum_{X\subset\Lambda}
\left(
\tau^{-t}_\Phi-\tau^{-t}_{\Phi|_\Lambda}
\right)(\Psi(X))
+
\sum_{X\subset\Lambda^c}
\left(
\tau^{-t}_\Phi-\tau^{-t}_{\Phi|_{\Lambda^c}}
\right)(\Psi(X))
+
\tau^{-t}_\Phi(W_\Lambda(\Psi)). 
\label{eq:surf_energy_formula}
\end{equation}

\label{lem:delta_t}
Under the above assumptions, the following hold.
\begin{romanenumerate}
\item 
${\mathfrak A}_\Lambda\subset\mathop{\mathrm{Dom}}\nolimits(\delta_t)$ for any $\Lambda\in{\mathcal F}$ . Moreover, there exists a constant $c_t$, depending
only on $\Phi$, $\Psi$, $\gamma$ and $t$, such that
\begin{equation}
\|\delta_t(A)\|\leq c_t|\Lambda|\|A\|
\label{eq:core_local_bound}
\end{equation}
for all $\Lambda\in{\mathcal F}$ and $A\in{\mathfrak A}_\Lambda$.
\item If in addition $\Psi\in\leftindex_1{\mathcal B}$, then 
$$
\delta_t(A)
=\mathrm{i}[H_\Lambda(\Psi|\Phi,t)+W_\Lambda(\Psi|\Phi,t),A]
=\lim_{\{\Lambda'\}}\mathrm{i}[H_{\Lambda'}(\Psi|\Phi,t),A]
$$
for any
$\Lambda\in{\mathcal F}$ and $A\in{\mathfrak A}_\Lambda$.

\end{romanenumerate}

By Proposition~\ref{prop:state_properties}\textup{(ii)}, $\omega_t$
is an $(\alpha,1)$-KMS state. Applying
\cite[Theorem~3.1]{Jaksic2023a} gives, for $A\in{\mathfrak A}_\Lambda$, $A>0$,
\begin{equation}
\mathrm{e}^{-\|W_\Lambda(t)\|-\|\alpha^{\mathrm{i}/2}(W_\Lambda(t))\|}
\leq
\frac{\omega_t(A)}{(\omega_t)_{-W_\Lambda(t)}(A)}
\leq
\mathrm{e}^{\|W_\Lambda(t)\|+
\|\alpha^{\mathrm{i}/2}_{-W_\Lambda(t)}(W_\Lambda(t))\|}.
\label{eq:boundsThm31}
\end{equation}
The assumptions and Theorem~\ref{thm:W_disapp} imply
\eqref{eq:WG_char}, proving the result.
\hfill$\Box$

\label{lem:alphactor}
For any $\Lambda\in{\mathcal F}$ and $s\in{\mathbbm R}$ one has 
\begin{equation} \alpha^s_{-W_{\Lambda}(t)}=\alpha^s_{\Lambda^c}\circ\alpha^s_\Lambda.
\label{mar-fac}
\end{equation}

\label{lem:WG_formula}  Let $\Lambda\in{\mathcal F}$ and $\Phi\in{\mathcal B}_\mathrm{f}$. Set
$R=\max\{\mathop{\oslash}\nolimits(X)\mid\Phi(X)\neq0\}$ if $\Phi\neq0$, and $R=0$ otherwise.
Then, for $|t|<\Theta_\Phi$, one has
\begin{align}
W_\Lambda(t)
&=W_\Lambda(\Psi)+\sum_{n\ge1}\frac{(-t)^n}{n!}
\sum_{X\in{\mathcal F},\boldsymbol{Y}\in{\mathcal C}_n(X,\partial \Lambda)}D_\Phi(\boldsymbol{Y})\Psi(X)
=\sum_{n\ge0}\frac{(-t)^n}{n!}
\sum_{X\in{\mathcal F},\boldsymbol{Y}\in{\mathcal C}_n(X,\partial \Lambda)}D_\Phi(\boldsymbol{Y})\Psi(X)\nonumber\\
&=W_\Lambda(\Psi)+\sum_{n\ge1}\frac{(-t)^n}{n!}
\sum_{\substack{X\in{\mathcal F}\\
X\in{\mathcal F}_\Lambda^\partial\ \text{or}\ X\cap{\mathcal T}^\Lambda_n\neq\emptyset}}
\sum_{\boldsymbol{Y}\in{\mathcal C}_n(X,\partial \Lambda)}D_\Phi(\boldsymbol{Y})\Psi(X),
\label{eq:formula_Wt}
\end{align}
where ${\mathcal T}^\Lambda_n=\{x\in{\mathbbm Z}^d\mid\mathop{\mathrm{dist}}\nolimits(\{x\},\partial\Lambda)\leq nR\}$.

\label{lem:HHhat}
\begin{romanenumerate}
\item If $n\geq L-1$, then, for every $\theta\geq0$,
$$
F_{L,n}(\theta)
\coloneq
\sum_{m\geq0}\frac{\theta^m}{m!}|{\mathcal C}'_{L,m}(n)|
=
\exp\left(
(n-L+1)\theta
+
2\sum_{q=1}^L\frac{\mathrm{e}^{q\theta}-1}{q}
\right).
$$

\item Let $K\subset{\mathbbm Z}$, $A\in{{\mathfrak{A}}_{\mathrm{loc}}}$, and let $J$ be a finite interval
containing $K\cap\mathop{\mathrm{supp}}\nolimits A$. Then, for every $m\geq0$,
\begin{equation}
\delta_{\Theta|_K}^m(A)
=
\sum_{\boldsymbol{y}\in{\mathcal C}'_{L,m}(J)}
D_{\widehat{\Theta}_K}(\boldsymbol{y})A.
\label{eq:restricted_block_iterates}
\end{equation}
\end{romanenumerate}
